"""Routes for Jobs, generated by Dryv; the engine implements EngineJobsService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Body, Depends, Path, Query, Request

from mzizi_engine.api.schemas.api.engine.enums.job_status import JobStatus
from mzizi_engine.api.schemas.api.engine.models.capability_list import CapabilityList
from mzizi_engine.api.schemas.api.engine.models.job import Job
from mzizi_engine.api.schemas.api.engine.models.job_list import JobList
from mzizi_engine.api.schemas.api.engine.models.submit_job_body import SubmitJobBody

__all__ = ["EngineJobsService", "build_engine_jobs_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class EngineJobsService(ABC):
    """What Jobs needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def cancel_job(self, *, job_id: UUID) -> Job:
        """Cancel a queued or running job."""

    @abstractmethod
    async def get_job(self, *, job_id: UUID) -> Job:
        """One job with its status and result."""

    @abstractmethod
    async def list_capabilities(self) -> CapabilityList:
        """What the engine can run."""

    @abstractmethod
    async def list_jobs(self, *, status: JobStatus | None, limit: int | None) -> JobList:
        """Recent jobs, newest first, optionally by status."""

    @abstractmethod
    async def submit_job(self, *, body: SubmitJobBody) -> Job:
        """Queue a job. Repeating an idempotency key returns the first job."""


def build_engine_jobs_router(service: EngineJobsService, guard: Guard | None = None) -> APIRouter:
    """Routes for Jobs, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Jobs"], dependencies=[Depends(guard)] if guard else [])

    @router.post(
        "/v1/jobs/{jobId}/cancel",
        response_model=Job,
        status_code=200,
        summary="Cancel a queued or running job.",
    )
    async def cancel_job(
        job_id: Annotated[UUID, Path(alias="jobId")],
    ) -> Job:
        return await service.cancel_job(job_id=job_id)

    @router.get(
        "/v1/jobs/{jobId}",
        response_model=Job,
        status_code=200,
        summary="One job with its status and result.",
    )
    async def get_job(
        job_id: Annotated[UUID, Path(alias="jobId")],
    ) -> Job:
        return await service.get_job(job_id=job_id)

    @router.get(
        "/capabilities",
        response_model=CapabilityList,
        status_code=200,
        summary="What the engine can run.",
    )
    async def list_capabilities() -> CapabilityList:
        return await service.list_capabilities()

    @router.get(
        "/v1/jobs",
        response_model=JobList,
        status_code=200,
        summary="Recent jobs, newest first, optionally by status.",
    )
    async def list_jobs(
        status: Annotated[JobStatus | None, Query(alias="status")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> JobList:
        return await service.list_jobs(status=status, limit=limit)

    @router.post(
        "/v1/jobs",
        response_model=Job,
        status_code=202,
        summary="Queue a job. Repeating an idempotency key returns the first job.",
    )
    async def submit_job(
        body: Annotated[SubmitJobBody, Body()],
    ) -> Job:
        return await service.submit_job(body=body)

    return router
